package swedueltest

import (
	"errors"
	"testing"
	"time"

	"github.com/golang-jwt/jwt/v5"
)

// Test_WithMaxAge_ValidToken tests that a token within the max age passes validation.
func Test_WithMaxAge_ValidToken(t *testing.T) {
	now := time.Now()
	iat := now.Add(-5 * time.Minute)

	claims := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(iat),
	}

	v := jwt.NewValidator(
		jwt.WithMaxAge(10*time.Minute),
		jwt.WithTimeFunc(func() time.Time { return now }),
	)

	err := v.Validate(claims)
	if err != nil {
		t.Errorf("expected no error for token within max age, got: %v", err)
	}
}

// Test_WithMaxAge_TooOldToken tests that a token exceeding the max age is rejected.
func Test_WithMaxAge_TooOldToken(t *testing.T) {
	now := time.Now()
	iat := now.Add(-15 * time.Minute)

	claims := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(iat),
	}

	v := jwt.NewValidator(
		jwt.WithMaxAge(10*time.Minute),
		jwt.WithTimeFunc(func() time.Time { return now }),
	)

	err := v.Validate(claims)
	if err == nil {
		t.Fatal("expected error for token exceeding max age, got nil")
	}
	if !errors.Is(err, jwt.ErrTokenTooOld) {
		t.Errorf("expected ErrTokenTooOld, got: %v", err)
	}
}

// Test_WithMaxAge_MissingIatClaim tests that a token without an iat claim
// is rejected when max age is configured.
func Test_WithMaxAge_MissingIatClaim(t *testing.T) {
	now := time.Now()

	claims := jwt.RegisteredClaims{} // no IssuedAt

	v := jwt.NewValidator(
		jwt.WithMaxAge(10*time.Minute),
		jwt.WithTimeFunc(func() time.Time { return now }),
	)

	err := v.Validate(claims)
	if err == nil {
		t.Fatal("expected error for missing iat claim with max age, got nil")
	}
	if !errors.Is(err, jwt.ErrTokenRequiredClaimMissing) {
		t.Errorf("expected ErrTokenRequiredClaimMissing, got: %v", err)
	}
}

// Test_WithMaxAge_WithLeeway tests that leeway is respected when checking max age.
func Test_WithMaxAge_WithLeeway(t *testing.T) {
	now := time.Now()
	// Token is 11 minutes old, max age is 10 minutes, but with 2 minute leeway it should pass
	iat := now.Add(-11 * time.Minute)

	claims := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(iat),
	}

	v := jwt.NewValidator(
		jwt.WithMaxAge(10*time.Minute),
		jwt.WithLeeway(2*time.Minute),
		jwt.WithTimeFunc(func() time.Time { return now }),
	)

	err := v.Validate(claims)
	if err != nil {
		t.Errorf("expected no error with leeway, got: %v", err)
	}
}

// Test_WithMaxAge_ExactlyAtBoundary tests that a token exactly at the max age boundary passes.
// Note: NewNumericDate truncates to seconds (TimePrecision), so we must also truncate
// our comparison time to avoid sub-second boundary false positives.
func Test_WithMaxAge_ExactlyAtBoundary(t *testing.T) {
	now := time.Now().Truncate(time.Second)
	iat := now.Add(-10 * time.Minute)

	claims := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(iat),
	}

	v := jwt.NewValidator(
		jwt.WithMaxAge(10*time.Minute),
		jwt.WithTimeFunc(func() time.Time { return now }),
	)

	err := v.Validate(claims)
	if err != nil {
		t.Errorf("expected no error at exact boundary, got: %v", err)
	}
}

// Test_WithMaxAge_JustOverBoundary tests that a token just over the max age is rejected.
func Test_WithMaxAge_JustOverBoundary(t *testing.T) {
	now := time.Now()
	// 10 minutes and 1 nanosecond over the boundary
	iat := now.Add(-10*time.Minute - 1*time.Nanosecond)

	claims := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(iat),
	}

	v := jwt.NewValidator(
		jwt.WithMaxAge(10*time.Minute),
		jwt.WithTimeFunc(func() time.Time { return now }),
	)

	err := v.Validate(claims)
	if err == nil {
		t.Fatal("expected error for token just over max age boundary, got nil")
	}
	if !errors.Is(err, jwt.ErrTokenTooOld) {
		t.Errorf("expected ErrTokenTooOld, got: %v", err)
	}
}

// Test_WithMaxAge_ZeroMaxAge tests that a zero max age does not enforce the check.
func Test_WithMaxAge_ZeroMaxAge(t *testing.T) {
	now := time.Now()
	iat := now.Add(-1 * time.Hour) // way older than any reasonable max age

	claims := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(iat),
	}

	v := jwt.NewValidator(
		jwt.WithMaxAge(0), // zero means disabled
		jwt.WithTimeFunc(func() time.Time { return now }),
	)

	err := v.Validate(claims)
	if err != nil {
		t.Errorf("expected no error with zero max age, got: %v", err)
	}
}

// Test_WithMaxAge_MapClaims tests max age validation with MapClaims.
func Test_WithMaxAge_MapClaims(t *testing.T) {
	now := time.Now()
	iat := now.Add(-5 * time.Minute)

	claims := jwt.MapClaims{
		"iat": float64(iat.Unix()),
	}

	v := jwt.NewValidator(
		jwt.WithMaxAge(10*time.Minute),
		jwt.WithTimeFunc(func() time.Time { return now }),
	)

	err := v.Validate(claims)
	if err != nil {
		t.Errorf("expected no error for MapClaims within max age, got: %v", err)
	}
}

// Test_WithMaxAge_CombinedValidation tests that max age errors are combined
// with other validation errors.
func Test_WithMaxAge_CombinedValidation(t *testing.T) {
	now := time.Now()
	iat := now.Add(-15 * time.Minute)

	// Token is too old AND has an invalid issuer
	claims := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(iat),
		Issuer:   "wrong-issuer",
	}

	v := jwt.NewValidator(
		jwt.WithMaxAge(10*time.Minute),
		jwt.WithIssuer("expected-issuer"),
		jwt.WithTimeFunc(func() time.Time { return now }),
	)

	err := v.Validate(claims)
	if err == nil {
		t.Fatal("expected combined errors, got nil")
	}
	if !errors.Is(err, jwt.ErrTokenTooOld) {
		t.Errorf("expected ErrTokenTooOld in combined errors, got: %v", err)
	}
	if !errors.Is(err, jwt.ErrTokenInvalidIssuer) {
		t.Errorf("expected ErrTokenInvalidIssuer in combined errors, got: %v", err)
	}
}

