package swedueltest

import (
	"errors"
	"testing"
	"time"

	"github.com/golang-jwt/jwt/v5"
)

// Test_Bug_MaxAgeLeewayNotDoubled verifies that the leeway is applied exactly
// once in the maxAge check. A token aged maxAge + leeway + 1ns should be
// rejected. If the leeway is accidentally applied twice (double-leeway bug),
// this token would be incorrectly accepted.
func Test_Bug_MaxAgeLeewayNotDoubled(t *testing.T) {
	now := time.Now()
	maxAge := 10 * time.Minute
	leeway := 2 * time.Minute

	// Token is 12 minutes and 1 nanosecond old — exactly leeway past the
	// maxAge boundary. With single leeway (10 + 2 = 12 min), this token
	// should be REJECTED. With double leeway (10 + 2 + 2 = 14 min), it
	// would be incorrectly ACCEPTED.
	iat := now.Add(-maxAge).Add(-leeway).Add(-1 * time.Nanosecond)

	claims := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(iat),
	}

	v := jwt.NewValidator(
		jwt.WithMaxAge(maxAge),
		jwt.WithLeeway(leeway),
		jwt.WithTimeFunc(func() time.Time { return now }),
	)

	err := v.Validate(claims)
	if err == nil {
		t.Fatal("expected error for token exceeding maxAge + leeway, got nil")
	}
	if !errors.Is(err, jwt.ErrTokenTooOld) {
		t.Errorf("expected ErrTokenTooOld, got: %v", err)
	}
}

// Test_Bug_MaxAgeLeewayExactBoundary verifies the exact boundary with leeway.
// A token exactly at maxAge + leeway should be accepted (single leeway).
// If leeway is doubled, this would also be accepted, but the test above
// (Test_Bug_MaxAgeLeewayNotDoubled) is the one that truly distinguishes
// single vs double leeway.
func Test_Bug_MaxAgeLeewayExactBoundary(t *testing.T) {
	now := time.Now().Truncate(time.Second)
	maxAge := 10 * time.Minute
	leeway := 2 * time.Minute

	// Token is exactly maxAge + leeway old — should be accepted.
	iat := now.Add(-maxAge).Add(-leeway)

	claims := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(iat),
	}

	v := jwt.NewValidator(
		jwt.WithMaxAge(maxAge),
		jwt.WithLeeway(leeway),
		jwt.WithTimeFunc(func() time.Time { return now }),
	)

	err := v.Validate(claims)
	if err != nil {
		t.Errorf("expected no error for token at exactly maxAge + leeway, got: %v", err)
	}
}

